INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (37, 'Chaquetas Topo Oscuro', 'Cazadora bomber ligeramente acolchada en nailon ligero, con cuello de peluche y cierre delantero con cremallera. Cuenta con bolsillo con cremallera en la manga, bolsillos laterales con solapa y botón de presión oculto, y un bolsillo interior con botón de presión. Remates acanalados anchos en puños y bajo, corte holgado que crea una silueta amplia sin ser oversize, y forro completo para mayor comodidad y calidez.', '36237157b3ae1c49eeb14e73f38f4572669cc7df.avif', 'activo', 229.9, 21, 'Hombres', 'Chaquetas', 'Topo oscuro, Liso', 'XS, S, M, L, XL, XXL', 309.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (38, 'Chaquetas Negro', 'Cazadora bomber ligeramente acolchada en nailon ligero con efecto lavado, con cuello y cierre delantero de cremallera. Incluye bolsillo con cremallera en la manga, bolsillos delanteros de parche con solapa y botón de presión, y bolsillo interior insertado con botón de presión oculto. Puños y bajo con elástico revestido y forro completo, combinando estilo moderno, funcionalidad y comodidad.
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (39, 'Chaquetas Beige Empolvado', 'Cazadora bomber ligeramente acolchada en nailon, con cuello elevado de canalé y cierre delantero con cremallera. Incluye bolsillos insertados al bies con botón de presión, bolsillo con cremallera en la manga y dos bolsillos interiores con botón de presión. Remates acanalados anchos en puños y bajo. Forro completo para mayor comodidad y abrigo.', 'e2a4c45def96b2bbe5b1a730c919ac5d00fe8ae0.avif', 'activo', 199.9, 25, 'Hombres', 'Chaquetas', 'Beige empolvado, Liso', 'XS, S, M, L, XL, XXL', 249.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (40, 'Chaquetas Marrón Oscuro', 'Cazadora en piel suave, con cuello, cierre de cremallera y solapa cortavientos con dos botones de presión visibles. Hombros caídos, bolsillos delanteros de parche con solapa y botón de presión, y bolsillos calientamanos en la parte posterior. Canesú en la espalda y elástico fruncido en puños y bajo. Forrada para mayor comodidad y abrigo.', 'ab29586fab912c76b888c7b4d1810d7990397388.avif', 'activo', 279.9, 36, 'Hombres', 'Chaquetas', 'Marrón oscuro, Liso', 'XS, S, M, L, XL, XXL', 219.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (41, 'Chaquetas Azul Marino', 'Cazadora bomber en nailon fresco con cuello y cremallera delante. Bolsillo con cremallera en una manga, bolsillos delanteros de parche con solapa y botón de presión, y un bolsillo interior insertado con botón de presión oculto. Elástico fruncido en puños y bajo. Forrada.
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (49, 'Calzado Castaño', 'Zapatos Oxford impermeables de última generación, ideales tanto para la oficina como para el fin de semana. Parte superior de piel Timberland resistente al agua, cordones de algodón, forro ecológico con 50% de plástico reciclado y plantilla viscoelástica Ortholite que se adapta al pie. Entresuela de EVA de alta amortiguación y suela de goma para durabilidad y tracción. Costuras selladas para evitar filtraciones de agua.', '51-zsMTeHZL._AC_SY575_.jpg', 'activo', 419.3, 13, 'Hombres', 'Calzado', 'Castaño', '38, 39, 40, 41, 42', 268.36, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (50, 'Calzado Beige', 'Zapatillas casuales de hombre, frescas, ligeras y cómodas para uso diario. Parte superior de microfibra de 1,2 mm con perforaciones que mejora la ventilación y absorbe la humedad. Puntera espaciosa para mayor libertad de movimiento, plantilla extraíble y lavable para personalizar la comodidad. Suela de goma antideslizante y resistente al desgaste. Perfectas para la oficina, el fin de semana o entrenamientos ligeros.', '71vTMfQfOoL._AC_SY695_.jpg', 'activo', 189.9, 27, 'Hombres', 'Calzado', 'Beige', '38, 39, 40, 41, 42', 109.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (51, 'Calzado Azul', 'Zapatos casuales de hombre, cómodos, ligeros y transpirables, perfectos para el verano y el uso diario. Parte superior de punto que permite la ventilación, suela de EVA y plantilla de espuma viscoelástica que absorbe impactos y proporciona amortiguación. Diseño con cordones, cuello elástico y lengüeta trasera para fácil colocación y protección del talón. Estilo casual y semiformal, ideal tanto para oficina como para ocasiones casuales.', '81z0Bt6erVL._AC_SY575_.jpg', 'activo', 199.9, 12, 'Hombres', 'Calzado', 'Azul', '38, 39, 40, 41, 42', 121.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (52, 'Calzado Blanco Negro', 'Zapatillas casuales versátiles para hombre, cómodas y transpirables, ideales para el uso diario. Diseño con cordones ajustables para un calce personalizado, perforaciones que permiten la ventilación y entresuela acolchada que brinda soporte en cada paso. Suela de goma antideslizante y resistente al desgaste para mayor durabilidad. Perfectas para completar cualquier look casual o semiformal.', '61CoFqjeGbL._AC_SY575_.jpg', 'activo', 209.9, 33, 'Hombres', 'Calzado', 'Blanco Negro', '38, 39, 40, 41, 42', 129.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (53, 'Calzado Blanco', 'Zapatillas casuales para hombre, que combinan estilo, comodidad y ligereza. Parte superior con costuras acolchadas que ofrecen estabilidad y protección. Suela de goma ligera de 340 g (talla 9) resistente a resbalones y desgaste. Puntera espaciosa que permite libertad de movimiento, plantilla extraíble y lavable para personalizar la comodidad. Diseño con cordones, perfecto para looks relajados o actividades ligeras.', '61OOMN7fMIL._AC_SY695_.jpg', 'activo', 219.9, 36, 'Hombres', 'Calzado', 'Blanco', '38, 39, 40, 41, 42', 139.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (54, 'Calzado  Negro', 'Zapatillas casuales de hombre: combinan estilo y comodidad con parte superior acolchada que brinda estabilidad y protección. Ultraligeras (340 g, talla 9) con suela de goma resistente a resbalones y desgaste. Puntera espaciosa para libertad de movimiento y plantilla extraíble y lavable para mayor confort. Diseño con cordones, perfectas para looks relajados, paseos informales o entrenamientos ligeros.', '61rR+Zb4XWL._AC_SY575_.jpg', 'activo', 229.9, 21, 'Hombres', 'Calzado', ' Negro', '38, 39, 40, 41, 42', 149.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (55, 'Calzado  Blanco Negro', 'Zapatillas retro de hombre, combinan estilo clásico y moderno con parte superior de cuero PU suave y gamuza para una estética elegante y minimalista. Construcción transpirable con malla que mantiene los pies frescos, forro de tela suave y plantilla de felpa para máxima comodidad. Suela desgastada que brinda tracción confiable y un toque visual único. Versátiles para looks casuales o deportivos.', '71URxQVHQEL._AC_SY575_.jpg', 'activo', 259.9, 25, 'Hombres', 'Calzado', ' Blanco/Negro', '38, 39, 40, 41, 42', 179.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (56, 'Calzado Blanco Gris Negro', 'Zapatillas retro de hombre: combinan estilo clásico y moderno con parte superior de cuero PU suave y gamuza para un look elegante y minimalista. Construcción transpirable con malla que mantiene los pies frescos, forro de tela suave y plantilla de felpa que ofrece comodidad todo el día. Suela desgastada para tracción confiable y diseño visual único. Versátiles para cualquier ocasión, casual o deportiva.', '71lWmfzJpWL._AC_SY575_.jpg', 'activo', 279.9, 12, 'Hombres', 'Calzado', 'Blanco/Gris/Negro', '38, 39, 40, 41, 42', 189.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (57, 'Calzado Marrón Claro', 'Oxford casuales slip-on para hombre: fáciles de poner, ligeros y transpirables. Parte superior de piel flexible y elástica que ofrece comodidad y ventilación natural. Suela atlética que mejora la tracción y la durabilidad, ideal para caminar con estabilidad y confianza. Versátiles para uso diario, combinan con vaqueros o pantalones deportivos para un look informal y cómodo.', '81mq8Y7CJwL._AC_SY575_.jpg', 'activo', 249.9, 14, 'Hombres', 'Calzado', 'Marrón Claro', '38, 39, 40, 41, 42', 159.9, TRUE);
