INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (130, 'Mono Crema Floral rojo', 'Mono en tejido vaporoso de algodón con tirantes elásticos de volante. Modelo con cuerpo nido de abeja, escote recto con ribete de volante y perneras largas de corte holgado.
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (131, 'Conjunto Beige Rayas Verdes', 'Conjunto de dos piezas formado por una ranita en lino suave y un body en punto suave de algodón. Ranita con escote cuadrado y tirantes ajustables con botón que se cruzan en la espalda. Elástico revestido suave en cintura y perneras. Body de manga corta con cuello redondo y abertura con botones de presión en un hombro (excepto en tallas 98–104) y en la entrepierna para facilitar el cambio de pañal. La colección H&M Adorables ofrece una cuidadosa selección de prendas atemporales de calidad con un confort excepcional.
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (132, 'Vestidos Rosa Claro Cuadros', 'Vestido en tejido suave de algodón de alta calidad con inserciones de encaje y body cosido. Modelo con cuello redondo, volantes sobrehilados delante que continúan por hombros y espalda, y abertura con botones detrás. Cintura fruncida y falda acampanada con bajo festoneado. Body con botones de presión en la entrepierna y elástico revestido fino alrededor de las perneras. La colección H&M Adorables ofrece una cuidadosa selección de prendas atemporales de calidad con un confort excepcional.', 'eb1aa14fc87da9add5afe4ca93a08d4dde96aae3.avif', 'activo', 31.9, 26, 'Niños', 'Bebés', 'Rosa claro/Cuadros', '2–4 meses 4–6 meses  6–9 meses 9–12 meses', 39.9, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (133, 'Patucos Beige Claro', 'Patucos para bebé con cordón de ajuste fino en el tobillo y caña plegable en canalé, confeccionados en lana suave al tacto, con regulación natural de temperatura y confort excepcional. Parte de la colección premium H&M Adorables.', '26e65e3fd013fd66c185f9b8d61abb3a26d80455.avif', 'activo', 92, 27, 'Niños', 'Bebés', 'Beige claro', ' Única / Ajustable', 104, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (134, 'Conjunto Beige Claro Floral', 'Conjunto de dos piezas de la colección H&M Adorables confeccionado en punto pointelle suave de algodón de alta calidad con mezcla de lyocell. Incluye un body de manga larga con frente cruzado, cierre de botones de presión y lazos, además de dos hileras de botones de presión en la entrepierna para ajustar el largo y cambiar el pañal fácilmente. Completan el conjunto unos leggings con cintura elástica revestida. El tejido es de alto gramaje, lo que brinda mayor grosor, durabilidad y comodidad.', '5fe62dfc1ccc2020c0ae0c0c96fb4a788bc75286.avif', 'activo', 115, 26, 'Niños', 'Bebés', 'Beige claro/Floral', '2–4 meses 4–6 meses  6–9 meses 9–12 meses', 130, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (135, 'Pack Beige Floral', 'Bodies de manga corta confeccionados en punto acanalado suave de algodón de alta calidad. Cuentan con un diseño cruzado y botones de presión en los laterales y en la entrepierna para facilitar el cambio de pañal. Las costuras fruncidas en las perneras aseguran un ajuste cómodo y seguro. El tejido de alto gramaje aporta mayor grosor y durabilidad sin comprometer la comodidad. Parte de la colección H&M Adorables, diseñada para ofrece', '259d34c04b63643eada9a54cb8d6437aed35ff66.avif', 'activo', 39.9, 29, 'Niños', 'Bebés', 'Beige/Floral', '2-4 meses  4–6 meses  6–9 meses  9–12 meses ', 31.92, TRUE);
INSERT INTO productos (id_producto, nombre, descripcion, foto, estado, precio, cantidad_stock, categoria, subcategoria, colores, tallas, "precioAnterior", "esNuevo") VALUES (136, 'Conjunto Blanco Floral', 'Conjunto de dos piezas en algodón de alta calidad. Camiseta de manga corta en punto suave. Modelo con detalle bordado delante y ribete de popelina en el cuello que continúa por un hombro e incorpora botones para facilitar el vestido. Pantalón corto en popelina vaporosa con cinturilla elástica ajustable y ribete de volante con acabado sobrehilado en los bajos. La colección H&M Adorables ofrece una cuidadosa selección de prendas atemporales de calidad con un confort excepcional.
